import React, { useState, useEffect, useMemo, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { 
  Search, SlidersHorizontal, Star, Plus, Minus, Home, LayoutGrid, Tag, Info, Heart
} from 'lucide-react';
import { categories, products, offers } from './data/menu';

const categoryImages = {
  all: "https://images.unsplash.com/photo-1414235077428-338989a2e8c0?auto=format&fit=crop&w=150&q=80",
  sandwich: "https://images.unsplash.com/photo-1528735602780-2552fd46c7af?auto=format&fit=crop&w=150&q=80",
  jain: "https://images.unsplash.com/photo-1546069901-ba9599a7e63c?auto=format&fit=crop&w=150&q=80",
  grill: "https://images.unsplash.com/photo-1539252554452-da6aec9d11f4?auto=format&fit=crop&w=150&q=80",
  'special-grill': "https://images.unsplash.com/photo-1509722747041-619f382b8d2d?auto=format&fit=crop&w=150&q=80",
  'jumbo-grill': "https://images.unsplash.com/photo-1565299624946-b28f40a0ae38?auto=format&fit=crop&w=150&q=80",
  pizza: "https://images.unsplash.com/photo-1513104890138-7c749659a591?auto=format&fit=crop&w=150&q=80",
  burger: "https://images.unsplash.com/photo-1568901346375-23c9450c58cd?auto=format&fit=crop&w=150&q=80",
  paratha: "https://images.unsplash.com/photo-1626776876729-bab4369a5a54?auto=format&fit=crop&w=150&q=80",
  khulcha: "https://images.unsplash.com/photo-1601050690597-df0568f70950?auto=format&fit=crop&w=150&q=80",
  frankie: "https://images.unsplash.com/photo-1589135398309-1144c5b16e15?auto=format&fit=crop&w=150&q=80",
  'hot-dog': "https://images.unsplash.com/photo-1541214113241-21578d2d9b62?auto=format&fit=crop&w=150&q=80",
  'french-fries': "https://images.unsplash.com/photo-1573080496219-bb080dd4f877?auto=format&fit=crop&w=150&q=80",
  'garlic-bread': "https://images.unsplash.com/photo-1573140247632-f8fd74997d5c?auto=format&fit=crop&w=150&q=80",
  juices: "https://images.unsplash.com/photo-1600271886342-ad92c39b95a9?auto=format&fit=crop&w=150&q=80",
  beverages: "https://images.unsplash.com/photo-1499638673689-79a0b5115d87?auto=format&fit=crop&w=150&q=80",
  extras: "https://images.unsplash.com/photo-1585238342024-78d387f4a707?auto=format&fit=crop&w=150&q=80",
};

const App = () => {
  const [activeCategory, setActiveCategory] = useState('all');
  const [sandwichOnly, setSandwichOnly] = useState(false);
  const [cart, setCart] = useState({});
  const [searchQuery, setSearchQuery] = useState('');
  const [scrolled, setScrolled] = useState(false);
  const [activeOffer, setActiveOffer] = useState(0);
  const offerRef = useRef(null);

  useEffect(() => {
    const handleScroll = () => setScrolled(window.scrollY > 20);
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  // Auto-slide offers
  useEffect(() => {
    const timer = setInterval(() => {
      setActiveOffer((prev) => (prev + 1) % offers.length);
    }, 4000);
    return () => clearInterval(timer);
  }, []);

  useEffect(() => {
    if (offerRef.current) {
      offerRef.current.scrollTo({
        left: activeOffer * (offerRef.current.offsetWidth - 40),
        behavior: 'smooth'
      });
    }
  }, [activeOffer]);

  const filteredProducts = useMemo(() => {
    return products.filter(product => {
      const matchesCategory = activeCategory === 'all' || product.category === activeCategory;
      const matchesSearch = product.name.toLowerCase().includes(searchQuery.toLowerCase());
      const isSandwichRelated = ['sandwich', 'grill', 'special-grill', 'jumbo-grill'].includes(product.category);
      const matchesSandwichToggle = !sandwichOnly || isSandwichRelated;

      return matchesCategory && matchesSearch && matchesSandwichToggle;
    });
  }, [activeCategory, searchQuery, sandwichOnly]);

  const updateCart = (id, delta) => {
    setCart(prev => {
      const newQty = (prev[id] || 0) + delta;
      if (newQty <= 0) {
        const { [id]: _, ...rest } = prev;
        return rest;
      }
      return { ...prev, [id]: newQty };
    });
  };

  return (
    <div className="max-w-[480px] mx-auto min-h-screen bg-background pb-32 selection:bg-primary/20">
      {/* HEADER - BRAND FOCUSED */}
      <header className={`fixed top-0 left-0 right-0 z-[60] transition-all duration-500 ${
        scrolled ? 'glass-effect py-2 shadow-lg shadow-black/5' : 'bg-transparent py-4'
      }`}>
        <div className="max-w-[480px] mx-auto px-5 flex items-center justify-center">
          <img 
            src="/logo.webp" 
            alt="Restaurant Logo" 
            className="h-[52px] w-auto object-contain"
          />
        </div>
      </header>

      <main className="pt-24 px-5">
        {/* SEARCH SECTION WITH INTEGRATED TOGGLE */}
        <section className="mb-8 flex items-center gap-3">
          <div className="relative flex-1 group">
            <div className="absolute left-5 top-1/2 -translate-y-1/2 text-slate-400 transition-colors group-focus-within:text-primary">
              <Search size={20} />
            </div>
            <input 
              type="text"
              placeholder="Search food..."
              className="w-full bg-white h-14 pl-14 pr-12 rounded-3xl shadow-sm border-2 border-transparent focus:border-primary/10 focus:ring-4 focus:ring-primary/5 transition-all outline-none text-slate-700 font-medium placeholder:text-slate-300"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
            />
            <div className="absolute right-5 top-1/2 -translate-y-1/2 text-slate-400">
              <SlidersHorizontal size={18} />
            </div>
          </div>

          <button 
            onClick={() => setSandwichOnly(!sandwichOnly)}
            className={`flex items-center gap-2 p-1 pr-3 rounded-full transition-all duration-300 border ${
              sandwichOnly 
              ? 'bg-primary border-primary text-white shadow-md shadow-primary/20' 
              : 'bg-white border-slate-100 text-slate-500'
            }`}
          >
            <div className={`w-10 h-10 rounded-full flex items-center justify-center text-lg ${sandwichOnly ? 'bg-white/20' : 'bg-slate-50'}`}>
              🥪
            </div>
            <span className="text-xs font-bold whitespace-nowrap hidden sm:block">Sandwich</span>
            <div className={`w-6 h-3.5 rounded-full relative border ${sandwichOnly ? 'bg-white/20 border-white/30' : 'bg-slate-200 border-slate-300'}`}>
              <motion.div 
                animate={{ x: sandwichOnly ? 12 : 2 }}
                className={`absolute top-0.5 w-2 h-2 rounded-full ${sandwichOnly ? 'bg-white' : 'bg-slate-400'}`}
              />
            </div>
          </button>
        </section>

        {/* OFFERS HERO */}
        <section className="mb-10 -mx-5 overflow-hidden">
          <div 
            ref={offerRef}
            className="flex gap-4 overflow-x-auto no-scrollbar px-5 py-2 scroll-smooth"
          >
            {offers.map((offer, i) => (
              <motion.div 
                key={offer.id}
                whileTap={{ scale: 0.97 }}
                className="min-w-[85%] h-44 rounded-3xl relative overflow-hidden shadow-xl"
              >
                <img src={offer.image} alt={offer.title} className="absolute inset-0 w-full h-full object-cover" />
                <div className={`absolute inset-0 bg-gradient-to-r ${offer.color.replace('bg-', 'from-')}/80 to-transparent flex flex-col justify-center px-8`}>
                  <motion.span 
                    initial={{ x: -20, opacity: 0 }}
                    whileInView={{ x: 0, opacity: 1 }}
                    className="text-white/80 text-xs font-black uppercase tracking-widest mb-1"
                  >
                    Special Offer
                  </motion.span>
                  <h3 className="text-white font-black text-2xl leading-none mb-1">{offer.title}</h3>
                  <p className="text-white/90 text-sm font-bold">{offer.subtitle}</p>
                </div>
              </motion.div>
            ))}
          </div>
          <div className="flex justify-center gap-2 mt-5">
            {offers.map((_, i) => (
              <motion.div 
                key={i} 
                animate={{ width: i === activeOffer ? 24 : 8 }}
                className={`h-2 rounded-full transition-colors duration-300 ${i === activeOffer ? 'bg-primary' : 'bg-slate-200'}`} 
              />
            ))}
          </div>
        </section>

        {/* CATEGORY SECTION - REAL FOOD IMAGES */}
        <section className="mb-12">
          <div className="flex items-center justify-between mb-6">
            <h2 className="font-black text-xl text-slate-800 tracking-tight">Top Categories</h2>
            <button className="text-primary text-xs font-bold uppercase tracking-widest">View All</button>
          </div>
          <div className="flex gap-4 overflow-x-auto no-scrollbar -mx-5 px-5 snap-x snap-mandatory h-[130px] items-center">
            {categories.map((cat) => (
              <motion.button
                key={cat.id}
                whileTap={{ scale: 0.95 }}
                onClick={() => setActiveCategory(cat.id)}
                className={`flex flex-col items-center gap-2 min-w-[90px] h-[110px] p-2 rounded-[24px] transition-all duration-300 snap-center ${
                  activeCategory === cat.id 
                  ? 'bg-white shadow-xl shadow-primary/10 border-2 border-primary/20' 
                  : 'bg-white shadow-sm border-2 border-transparent'
                }`}
              >
                <div className="w-14 h-14 rounded-full overflow-hidden mb-1">
                  <img 
                    src={categoryImages[cat.id] || categoryImages.all} 
                    alt={cat.name}
                    className={`w-full h-full object-cover transition-transform duration-500 ${activeCategory === cat.id ? 'scale-110' : ''}`}
                  />
                </div>
                <span className={`text-[10px] font-bold uppercase tracking-wider text-center leading-tight ${
                  activeCategory === cat.id ? 'text-primary' : 'text-slate-500'
                }`}>
                  {cat.name}
                </span>
                {activeCategory === cat.id && (
                  <motion.div layoutId="activeDot" className="w-1 h-1 bg-primary rounded-full" />
                )}
              </motion.button>
            ))}
          </div>
        </section>

        {/* FILTER CHIPS (Sticky) */}
        <div className="sticky top-[72px] z-40 bg-background/95 backdrop-blur-md -mx-5 px-5 py-4 mb-8 flex gap-2 overflow-x-auto no-scrollbar border-y border-slate-100/50">
          {['⭐ Best Sellers', '🔥 Popular', '₹ Under 99', '🧀 Cheese Lovers', '🌶️ Spicy'].map((chip) => (
            <motion.button 
              key={chip}
              whileTap={{ scale: 0.95 }}
              className="px-5 py-2.5 bg-white border border-slate-100 rounded-2xl whitespace-nowrap text-xs font-bold text-slate-600 shadow-sm hover:border-primary/20 transition-colors"
            >
              {chip}
            </motion.button>
          ))}
        </div>

        {/* PRODUCT LIST - REDESIGNED GRID */}
        <section className="grid grid-cols-2 gap-4 mb-10">
          <AnimatePresence mode='popLayout'>
            {filteredProducts.map((product) => (
              <motion.div
                layout
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0, scale: 0.9 }}
                whileHover={{ y: -5 }}
                key={product.id}
                className="bg-white rounded-[24px] p-3 shadow-[0_8px_30px_rgb(0,0,0,0.04)] hover:shadow-[0_20px_40px_rgb(0,0,0,0.08)] transition-all duration-500 flex flex-col h-full group"
              >
                {/* Image Container */}
                <div className="relative aspect-square rounded-[24px] overflow-hidden mb-3 bg-slate-100">
                  <motion.img 
                    whileHover={{ scale: 1.1 }}
                    transition={{ duration: 0.6, ease: "easeOut" }}
                    src={`https://images.unsplash.com/photo-${1500000000000 + product.id}?auto=format&fit=crop&w=400&q=80`} 
                    alt={product.name}
                    loading="lazy"
                    className="w-full h-full object-cover"
                    onError={(e) => {
                      e.target.src = "https://images.unsplash.com/photo-1528735602780-2552fd46c7af?auto=format&fit=crop&w=400&q=80";
                    }}
                  />

                  {/* Badges Overlay */}
                  <div className="absolute top-2 left-2 flex flex-col gap-1.5 items-start">
                    {product.rating >= 4.8 && (
                      <span className="bg-orange-500 text-white text-[8px] font-bold px-2 py-1 rounded-full uppercase tracking-wider shadow-sm">Best Seller</span>
                    )}
                    {product.id % 5 === 0 && (
                      <span className="bg-blue-500 text-white text-[8px] font-bold px-2 py-1 rounded-full uppercase tracking-wider shadow-sm">Popular</span>
                    )}
                    {product.name.toLowerCase().includes('cheese') && (
                      <span className="bg-yellow-400 text-slate-900 text-[8px] font-bold px-2 py-1 rounded-full uppercase tracking-wider shadow-sm">Cheese Lover</span>
                    )}
                    {product.veg && (
                      <div className="w-4 h-4 border border-green-600 flex items-center justify-center bg-white/90 backdrop-blur-sm rounded-[4px] shadow-sm">
                        <div className="w-1.5 h-1.5 bg-green-600 rounded-full" />
                      </div>
                    )}
                  </div>

                  {/* Favourite Toggle */}
                  <button className="absolute top-2 right-2 p-1.5 bg-white/90 backdrop-blur-sm rounded-full text-slate-400 hover:text-red-500 transition-colors shadow-sm">
                    <Heart size={14} />
                  </button>
                </div>

                {/* Content Area */}
                <div className="flex-1 flex flex-col px-1">
                  <h3 className="font-semibold text-[18px] text-slate-800 line-clamp-2 leading-[1.2] mb-1 group-hover:text-primary transition-colors">
                    {product.name}
                  </h3>
                  <p className="text-[13px] text-slate-400 line-clamp-2 leading-relaxed font-medium mb-3">
                    {product.description}
                  </p>

                  <div className="mt-auto flex items-center justify-between gap-2">
                    <div className="flex flex-col">
                      <div className="flex items-center gap-1 mb-0.5">
                        <div className="bg-emerald-50 text-emerald-600 px-1.5 py-0.5 rounded-md flex items-center gap-0.5">
                          <Star size={10} className="fill-emerald-600" />
                          <span className="text-[10px] font-black">{product.rating}</span>
                        </div>
                      </div>
                      <span className="font-bold text-slate-900 text-[18px]">₹{product.price}</span>
                    </div>

                    <div className="relative">
                      <AnimatePresence mode='wait'>
                        {cart[product.id] ? (
                          <motion.div 
                            key="qty"
                            layout
                            initial={{ width: 40, opacity: 0 }}
                            animate={{ width: 84, opacity: 1 }}
                            exit={{ width: 40, opacity: 0 }}
                            className="flex items-center bg-primary text-white rounded-full h-9 p-0.5 shadow-lg shadow-primary/20"
                          >
                            <button 
                              onClick={() => updateCart(product.id, -1)}
                              className="w-7 h-7 flex items-center justify-center hover:bg-white/20 rounded-full transition-colors"
                            >
                              <Minus size={14} strokeWidth={3} />
                            </button>
                            <span className="flex-1 text-center font-bold text-sm">{cart[product.id]}</span>
                            <button 
                              onClick={() => updateCart(product.id, 1)}
                              className="w-7 h-7 flex items-center justify-center hover:bg-white/20 rounded-full transition-colors"
                            >
                              <Plus size={14} strokeWidth={3} />
                            </button>
                          </motion.div>
                        ) : (
                          <motion.button
                            key="add"
                            layout
                            initial={{ opacity: 0, scale: 0.8 }}
                            animate={{ opacity: 1, scale: 1 }}
                            whileTap={{ scale: 0.9 }}
                            onClick={() => updateCart(product.id, 1)}
                            className="w-9 h-9 bg-primary text-white flex items-center justify-center rounded-full shadow-lg shadow-primary/20 hover:shadow-primary/40 transition-all"
                          >
                            <Plus size={20} strokeWidth={3} />
                          </motion.button>
                        )}
                      </AnimatePresence>
                    </div>
                  </div>
                </div>
              </motion.div>
            ))}
          </AnimatePresence>
        </section>

        <div className="h-20 flex flex-col items-center justify-center opacity-30">
          <Info size={20} className="mb-2" />
          <p className="text-[10px] font-bold uppercase tracking-[0.3em]">End of Menu</p>
        </div>
      </main>

      {/* BOTTOM NAVIGATION */}
      <nav className="fixed bottom-8 left-1/2 -translate-x-1/2 w-[92%] max-w-[440px] bg-slate-900/95 backdrop-blur-2xl rounded-[32px] p-2.5 flex items-center justify-between shadow-2xl shadow-black/40 z-[100]">
        {[
          { id: 'home', icon: Home, label: 'Home' },
          { id: 'categories', icon: LayoutGrid, label: 'Browse' },
          { id: 'offers', icon: Tag, label: 'Deals' },
        ].map((item) => {
          const isActive = item.id === 'home';
          return (
            <motion.button
              key={item.id}
              whileTap={{ scale: 0.9 }}
              className={`relative flex items-center gap-2.5 px-5 py-3.5 rounded-[24px] transition-all duration-300 ${
                isActive ? 'bg-primary text-white shadow-lg shadow-primary/30' : 'text-slate-500 hover:text-slate-300'
              }`}
            >
              <item.icon size={20} strokeWidth={isActive ? 3 : 2} />
              {isActive && (
                <motion.span 
                  initial={{ width: 0, opacity: 0 }}
                  animate={{ width: 'auto', opacity: 1 }}
                  className="text-xs font-black tracking-wide"
                >
                  {item.label}
                </motion.span>
              )}
              {item.count > 0 && !isActive && (
                <span className="absolute top-2 right-3 w-4 h-4 bg-primary text-white text-[8px] font-black rounded-full flex items-center justify-center border border-slate-900">
                  {item.count}
                </span>
              )}
            </motion.button>
          );
        })}
      </nav>

      {/* CUSTOM CURSOR / TOUCH EFFECT */}
      <div className="fixed inset-0 pointer-events-none z-[200]">
        <div className="w-full h-full opacity-[0.03] bg-[url('https://www.transparenttextures.com/patterns/asfalt-dark.png')]" />
      </div>
    </div>
  );
};

export default App;
